import {
    Component,
    OnDestroy,
    OnInit,
    ChangeDetectionStrategy,
    ChangeDetectorRef,
} from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Subscription } from 'rxjs';
import { StoreDbService, OBJECTNAME } from 'godigital-lib';
import { BookingService, BookingDoc } from '../booking.service';

interface BoatDoc {
    boatId: string;
    boatSlug?: string;
    ownerId?: string;

    name?: string;
    model?: string;
    type?: string;

    capacity?: number;
    cabins?: number;
    bathrooms?: number;
    overnightGuests?: number;

    image?: string;
    heroImage?: string;
    gallery?: string[];
}

@Component({
    selector: 'app-boat-booking',
    templateUrl: './boat-booking.component.html',
    styleUrls: ['./boat-booking.component.css'],
    changeDetection: ChangeDetectionStrategy.OnPush
})
export class BoatBookingComponent implements OnInit, OnDestroy {

    mainpageId!: string;

    loading = false;
    submitting = false;
    error?: string;
    success?: { bookingId: string };

    boats: BoatDoc[] = [];
    selectedBoat?: BoatDoc;

    private subs = new Subscription();

    /** Optional: used to resolve storage relative paths if you display images */
    private readonly storageRootFolder = 'mainpages';
    private form: FormGroup;

    constructor(
        private route: ActivatedRoute,
        private storeDb: StoreDbService,
        private bookingService: BookingService,
        private fb: FormBuilder,
        private cdr: ChangeDetectorRef
    ) {
        this.form = this.fb.group({
            boatId: ['', Validators.required],

            // date & time
            date: ['', Validators.required],         // YYYY-MM-DD (from <input type="date">)
            startTime: ['09:00', Validators.required], // HH:mm
            durationHours: [8, [Validators.required, Validators.min(1), Validators.max(24)]],

            // party
            adults: [2, [Validators.required, Validators.min(1), Validators.max(50)]],
            children: [0, [Validators.required, Validators.min(0), Validators.max(50)]],

            // contact
            fullName: ['', [Validators.required, Validators.minLength(2)]],
            email: ['', [Validators.required, Validators.email]],
            phone: [''],

            // extras (example toggles)
            extraSkipper: [true],
            extraSeabob: [false],

            customerNote: ['']
        });


    }

    ngOnInit(): void {
        this.subs.add(
            this.route.queryParamMap.subscribe(params => {
                const rawFromQuery = params.get('mainpage');
                const raw = rawFromQuery || this.detectMainpageFromSubdomain() || 'layali';
                const id = this.normalizeMainpageId(raw);

                if (this.mainpageId === id) return;
                void this.loadContext(id);
            })
        );
    }

    ngOnDestroy(): void {
        this.subs.unsubscribe();
    }

    // ---------------------------------------------------------------------------
    // LOADERS
    // ---------------------------------------------------------------------------

    private async loadContext(mainpageId: string): Promise<void> {
        this.mainpageId = mainpageId;

        this.loading = true;
        this.error = undefined;
        this.success = undefined;
        this.boats = [];
        this.selectedBoat = undefined;
        this.form.reset({
            boatId: '',
            date: '',
            startTime: '09:00',
            durationHours: 8,
            adults: 2,
            children: 0,
            fullName: '',
            email: '',
            phone: '',
            extraSkipper: true,
            extraSeabob: false,
            customerNote: ''
        });

        this.cdr.markForCheck();

        try {
            await this.loadBoatsForMainpage(mainpageId);

            // auto-select first boat to avoid boatId missing
            if (this.boats.length) {
                this.selectBoat(this.boats[0]);
            } else {
                this.error = `No boat configured for ${mainpageId}.`;
            }
        } catch (e: any) {
            this.error = e?.message || 'Failed to load booking context.';
        } finally {
            this.loading = false;
            this.cdr.markForCheck();
        }
    }

    private async loadBoatsForMainpage(mainpageId: string): Promise<void> {
        // New RTDB structure (single catalog):
        // backendowners/boats/<boatId>/boat
        const node = await this.storeDb.getObject<any>('backendowners/boats', null as any);

        if (!node || typeof node !== 'object') {
            this.boats = [];
            return;
        }

        const boats: BoatDoc[] = Object.keys(node)
            .map(boatId => {
                const wrap = node[boatId] || {};
                const src = wrap.boat || wrap; // tolerate both shapes
                return {
                    boatId: String(src.boatId || boatId),
                    boatSlug: src.boatSlug,
                    ownerId: src.ownerId || mainpageId,
                    name: src.name,
                    model: src.model,
                    type: src.type,
                    capacity: src.capacity,
                    cabins: src.cabins,
                    bathrooms: src.bathrooms,
                    overnightGuests: src.overnightGuests,
                    image: src.image || src.mainImage,
                    heroImage: src.heroImage || src.mainImage,
                    gallery: Array.isArray(src.gallery) ? src.gallery : []
                } as BoatDoc;
            })
            .filter(b => !!b.boatId);

        // stable order: boatId
        boats.sort((a, b) => String(a.boatId).localeCompare(String(b.boatId)));
        this.boats = boats;
    }

    // ---------------------------------------------------------------------------
    // UI ACTIONS
    // ---------------------------------------------------------------------------

    selectBoat(b: BoatDoc): void {
        this.selectedBoat = b;
        this.form.patchValue({ boatId: b.boatId });
        this.error = undefined;
        this.success = undefined;
        this.cdr.markForCheck();
    }

    async submit(): Promise<void> {
        this.error = undefined;
        this.success = undefined;

        if (this.form.invalid) {
            this.form.markAllAsTouched();
            this.error = 'Please complete the form.';
            this.cdr.markForCheck();
            return;
        }

        const v = this.form.getRawValue();
        const boatId = String(v.boatId || '').trim();

        if (!boatId) {
            this.error = 'Boat is missing (boatId). Please select a boat.';
            this.cdr.markForCheck();
            return;
        }

        const boat = this.boats.find(x => x.boatId === boatId) || this.selectedBoat;
        if (!boat) {
            this.error = 'Selected boat not found.';
            this.cdr.markForCheck();
            return;
        }

        const adults = Number(v.adults || 0);
        const children = Number(v.children || 0);
        const total = adults + children;

        const { startAtIso, endAtIso } = this.computeStartEndIso(
            String(v.date),
            String(v.startTime),
            Number(v.durationHours || 0)
        );

        const extrasSelected: Record<string, boolean> = {
            skipper: !!v.extraSkipper,
            seabob: !!v.extraSeabob
        };

        // You can price later. For now, store selections only.
        const payload: Omit<BookingDoc, 'bookingId' | 'audit'> = {
            type: 'boat',
            status: 'requested',

            mainpageId: this.mainpageId,
            ownerId: boat.ownerId || this.mainpageId,
            boatId: boat.boatId,
            boatSlug: boat.boatSlug,

            time: { startAt: startAtIso, endAt: endAtIso },

            party: { adults, children, total },

            customer: {
                fullName: String(v.fullName || '').trim(),
                email: String(v.email || '').trim(),
                phone: String(v.phone || '').trim(),
                uid: this.storeDb.currentUser?.uid // optional if logged in
            },

            extras: {
                selected: extrasSelected
            },

            notes: {
                customerNote: String(v.customerNote || '').trim()
            }
        };

        this.submitting = true;
        this.cdr.markForCheck();

        try {
            const created = await this.bookingService.createBoatBooking(payload);
            this.success = { bookingId: created.bookingId };
            this.form.disable({ emitEvent: false });
        } catch (e: any) {
            this.error = e?.message || 'Booking failed.';
        } finally {
            this.submitting = false;
            this.cdr.markForCheck();
        }
    }

    reset(): void {
        this.form.enable({ emitEvent: false });
        this.success = undefined;
        this.error = undefined;

        // keep boat selection
        const boatId = this.selectedBoat?.boatId || '';
        this.form.patchValue({
            boatId,
            date: '',
            startTime: '09:00',
            durationHours: 8,
            adults: 2,
            children: 0,
            fullName: '',
            email: '',
            phone: '',
            extraSkipper: true,
            extraSeabob: false,
            customerNote: ''
        });
        this.cdr.markForCheck();
    }

    // ---------------------------------------------------------------------------
    // DATE HELPERS
    // ---------------------------------------------------------------------------

    private computeStartEndIso(dateYYYYMMDD: string, startHHmm: string, durationHours: number) {
        // Construct local datetime, then convert to ISO
        const [y, m, d] = dateYYYYMMDD.split('-').map(n => Number(n));
        const [hh, mm] = startHHmm.split(':').map(n => Number(n));

        const start = new Date(y, (m - 1), d, hh, mm, 0, 0);
        const end = new Date(start.getTime() + Math.max(0, durationHours) * 3600 * 1000);

        return { startAtIso: start.toISOString(), endAtIso: end.toISOString() };
    }

    // ---------------------------------------------------------------------------
    // MAINPAGE ID RESOLUTION (same spirit as your MainpageComponent)
    // ---------------------------------------------------------------------------

    private normalizeMainpageId(raw: string): string {
        const trimmed = (raw || '').trim().toLowerCase();
        if (trimmed.startsWith('owner-home-')) return trimmed;
        return `owner-home-${trimmed}`;
    }

    private detectMainpageFromSubdomain(): string | null {
        if (typeof window === 'undefined') return null;
        const host = window.location.hostname;
        const parts = host.split('.');
        if (parts.length > 2) {
            const sub = parts[0];
            if (sub && sub !== 'www' && sub !== 'localhost') return sub;
        }
        return null;
    }
}
