import { Injectable } from '@angular/core';
import { StoreDbService, OBJECTNAME } from 'godigital-lib';

export type BookingStatus =
  | 'requested'
  | 'confirmed'
  | 'cancelled'
  | 'declined'
  | 'expired'
  | 'completed';

export interface BookingDoc {
  bookingId: string;
  status: BookingStatus;
  type: 'boat' | 'event';
  mainpageId: string;
  ownerId: string;
  boatId: string;
  eventId?: string;

  customer: { uid: string; fullName: string; email: string; phone?: string };
  party: { adults: number; children: number; total: number };
  time: { startAt: string; endAt: string };

  locations: {
    pickup: { placeId?: string; label: string; lat?: number; lng?: number };
    dropoff: { placeId?: string; label: string; lat?: number; lng?: number };
  };

  extras: {
    selected: Record<string, boolean>;
    items?: Array<{ code: string; label: string; qty: number; unitPrice: number }>;
  };

  pricing: {
    currency: 'EUR';
    baseAmount: number;
    extrasAmount: number;
    serviceFee: number;
    totalAmount: number;
    depositAmount: number;
    taxAmount: number;
  };

  notes: { customerNote?: string; ownerNote?: string };

  audit: {
    createdAt: string;
    updatedAt: string;
    requestedAt?: string;
    confirmedAt?: string;
    cancelledAt?: string;
    cancelledBy?: 'customer' | 'owner' | 'system';
  };
}

@Injectable({ providedIn: 'root' })
export class OwnerBookingService {
  private readonly bookingsRoot = (OBJECTNAME as any).bnBookings || 'backendbookings';
  private readonly planningsRoot = 'backendplannings/boats';
  private readonly occupancyRoot = 'backendoccupancy/boats';

  constructor(private db: StoreDbService) {}

  // ----------------------------
  // READ
  // ----------------------------

  /** returns map bookingId->true */
  async getOwnerBookingIndex(ownerId: string): Promise<Record<string, true>> {
    return (await this.db.getObject<Record<string, true>>(
      `${this.bookingsRoot}/byOwner`,
      ownerId
    )) || {};
  }

  async getBookingById(bookingId: string): Promise<BookingDoc | null> {
    return await this.db.getObject<BookingDoc>(`${this.bookingsRoot}/byId`, bookingId);
  }

  /** convenience: loads full docs for owner */
  async listOwnerBookings(ownerId: string): Promise<BookingDoc[]> {
    const idx = await this.getOwnerBookingIndex(ownerId);
    const ids = Object.keys(idx || {});
    if (!ids.length) return [];

    const docs = await Promise.all(ids.map(id => this.getBookingById(id)));
    return docs
      .filter((x): x is BookingDoc => !!x)
      .sort((a, b) => (b.audit?.createdAt || '').localeCompare(a.audit?.createdAt || ''));
  }

  // ----------------------------
  // ACTIONS
  // ----------------------------

  async confirmBoatBooking(booking: BookingDoc): Promise<void> {
    if (!booking?.bookingId) throw new Error('Missing bookingId');
    if (booking.type !== 'boat') throw new Error('Only boat bookings supported in this method');

    const now = new Date().toISOString();

    // busy block path
    const busyPath = `${this.planningsRoot}/${booking.mainpageId}/${booking.boatId}/busyBlocks/${booking.bookingId}`;

    // occupancy paths
    const occupancyPaths = this.computeOccupancyPaths(
      booking.mainpageId,
      booking.boatId,
      new Date(booking.time.startAt),
      new Date(booking.time.endAt)
    );

    // confirm updates
    const updates: Record<string, any> = {
      [`${this.bookingsRoot}/byId/${booking.bookingId}/status`]: 'confirmed',
      [`${this.bookingsRoot}/byId/${booking.bookingId}/audit/updatedAt`]: now,
      [`${this.bookingsRoot}/byId/${booking.bookingId}/audit/confirmedAt`]: now,

      [busyPath]: {
        startAt: booking.time.startAt,
        endAt: booking.time.endAt,
        status: 'confirmed',
      },
    };

    // lock occupancy (idempotent)
    for (const p of occupancyPaths) updates[p] = booking.bookingId;

    await this.db.multiPathUpdate(updates);
  }

  async declineBooking(booking: BookingDoc, ownerNote = ''): Promise<void> {
    const now = new Date().toISOString();
    const updates: Record<string, any> = {
      [`${this.bookingsRoot}/byId/${booking.bookingId}/status`]: 'declined',
      [`${this.bookingsRoot}/byId/${booking.bookingId}/audit/updatedAt`]: now,
      [`${this.bookingsRoot}/byId/${booking.bookingId}/notes/ownerNote`]: ownerNote || '',
    };
    await this.db.multiPathUpdate(updates);
  }

  /**
   * Cancel:
   * - status=cancelled + audit fields
   * - remove busyBlock (if any)
   * - remove occupancy slots ONLY if they still point to this bookingId
   */
  async cancelBookingAsOwner(booking: BookingDoc, ownerNote = ''): Promise<void> {
    const now = new Date().toISOString();

    const updates: Record<string, any> = {
      [`${this.bookingsRoot}/byId/${booking.bookingId}/status`]: 'cancelled',
      [`${this.bookingsRoot}/byId/${booking.bookingId}/audit/updatedAt`]: now,
      [`${this.bookingsRoot}/byId/${booking.bookingId}/audit/cancelledAt`]: now,
      [`${this.bookingsRoot}/byId/${booking.bookingId}/audit/cancelledBy`]: 'owner',
      [`${this.bookingsRoot}/byId/${booking.bookingId}/notes/ownerNote`]: ownerNote || '',
    };

    if (booking.type === 'boat') {
      // remove busy block
      updates[`${
        this.planningsRoot
      }/${booking.mainpageId}/${booking.boatId}/busyBlocks/${booking.bookingId}`] = null;

      // remove occupancy slots safely: read day nodes and null only matching slots
      const start = new Date(booking.time.startAt);
      const end = new Date(booking.time.endAt);

      const dayKeys = this.enumerateDayKeys(start, end);
      for (const dayKey of dayKeys) {
        const dayNode = await this.db.getObject<any>(
          this.occupancyRoot,
          `${booking.mainpageId}/${booking.boatId}/${dayKey}`
        );

        if (!dayNode) continue;

        for (const slotKey of Object.keys(dayNode)) {
          if (dayNode[slotKey] === booking.bookingId) {
            updates[`${this.occupancyRoot}/${booking.mainpageId}/${booking.boatId}/${dayKey}/${slotKey}`] = null;
          }
        }
      }
    }

    await this.db.multiPathUpdate(updates);
  }

  // ----------------------------
  // SLOTS (hourly)
  // ----------------------------

  private computeOccupancyPaths(mainpageId: string, boatId: string, startAt: Date, endAt: Date): string[] {
    const paths: string[] = [];

    const cur = new Date(startAt);
    cur.setMinutes(0, 0, 0);

    const end = new Date(endAt);
    if (end.getMinutes() || end.getSeconds() || end.getMilliseconds()) end.setHours(end.getHours() + 1);
    end.setMinutes(0, 0, 0);

    while (cur < end) {
      const dayKey = this.toDayKey(cur);
      const slotKey = `H${String(cur.getHours()).padStart(2, '0')}`;
      paths.push(`${this.occupancyRoot}/${mainpageId}/${boatId}/${dayKey}/${slotKey}`);
      cur.setHours(cur.getHours() + 1);
    }
    return paths;
  }

  private enumerateDayKeys(startAt: Date, endAt: Date): string[] {
    const out: string[] = [];
    const cur = new Date(startAt);
    cur.setHours(0, 0, 0, 0);

    const end = new Date(endAt);
    end.setHours(0, 0, 0, 0);

    while (cur <= end) {
      out.push(this.toDayKey(cur));
      cur.setDate(cur.getDate() + 1);
    }
    return out;
  }

  private toDayKey(d: Date): string {
    const yyyy = d.getFullYear();
    const mm = String(d.getMonth() + 1).padStart(2, '0');
    const dd = String(d.getDate()).padStart(2, '0');
    return `${yyyy}${mm}${dd}`;
  }
}
