import { Injectable } from '@angular/core';
import firebase from 'firebase/compat/app';
import 'firebase/compat/database';
import { StoreDbService, OBJECTNAME } from 'godigital-lib';

export type BookingStatus = 'requested' | 'confirmed' | 'cancelled' | 'rejected';

export interface BookingDoc {
  bookingId: string;
  type: 'boat';

  status: BookingStatus;

  mainpageId: string;   // owner-home-layali
  ownerId: string;      // same as mainpageId in your model
  boatId: string;       // "1000002"
  boatSlug?: string;

  time: { startAt: string; endAt: string };
  party: { adults: number; children: number; total: number };

  customer: { fullName: string; email: string; phone?: string; uid?: string };

  extras?: {
    selected?: Record<string, boolean>;
    items?: Array<{ code: string; label: string; qty: number; unitPrice: number }>;
  };

  notes?: { customerNote?: string; ownerNote?: string };

  audit: { createdAt: string; updatedAt: string; requestedAt?: string };
}

@Injectable({ providedIn: 'root' })
export class BookingService {
  constructor(private storeDb: StoreDbService) {}

  /**
   * Flat write:
   * backendbookings/<bookingId> = BookingDoc
   */
  async createBoatBooking(input: Omit<BookingDoc, 'bookingId' | 'audit'>): Promise<BookingDoc> {
    if (!input?.mainpageId) throw new Error('mainpageId is required');
    if (!input?.ownerId) throw new Error('ownerId is required');
    if (!input?.boatId) throw new Error('boatId is required');

    const nowIso = new Date().toISOString();

    const root = (OBJECTNAME as any).bnBookings || 'backendbookings';
    const ref = this.storeDb.db.ref(root).push(); // generates RTDB push-id
    const bookingId = ref.key as string;

    const doc: BookingDoc = {
      ...input,
      bookingId,
      audit: {
        createdAt: nowIso,
        updatedAt: nowIso,
        requestedAt: nowIso
      }
    };

    await ref.set(doc);
    return doc;
  }

  async getBooking(bookingId: string): Promise<BookingDoc | null> {
    const root = (OBJECTNAME as any).bnBookings || 'backendbookings';
    return await this.storeDb.getObject<BookingDoc>(root, bookingId);
  }
}
