import { Component, ChangeDetectionStrategy, ChangeDetectorRef } from '@angular/core';
import { OwnerBookingService, BookingDoc } from '../owner-booking.service';
import { StoreDbService } from 'godigital-lib';

@Component({
  selector: 'app-owner-dashboard',
  templateUrl: './owner-dashboard.component.html',
  styleUrls: ['./owner-dashboard.component.css'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class OwnerDashboardComponent {
  ownerId = ''; // owner-home-xxx
  bookings: BookingDoc[] = [];
  selected?: BookingDoc;

  loading = false;
  error?: string;

  actionLoading = false;
  ownerNote = '';

  constructor(
    private bookingSvc: OwnerBookingService,
    private storeDb: StoreDbService,
    private cdr: ChangeDetectorRef
  ) {}

  async ngOnInit(): Promise<void> {
    // simplest: ownerId from current user profile OR query param OR hardcode for now
    // If you store ownerId somewhere else, plug it here.
    // For now, assume ownerId == mainpageId and it is in localStorage (example):
    this.ownerId = localStorage.getItem('ownerId') || 'owner-home-layali';

    await this.refresh();
  }

  async refresh(): Promise<void> {
    this.loading = true;
    this.error = undefined;
    this.selected = undefined;
    this.cdr.markForCheck();

    try {
      this.bookings = await this.bookingSvc.listOwnerBookings(this.ownerId);
    } catch (e: any) {
      this.error = e?.message || 'Failed to load owner bookings.';
    } finally {
      this.loading = false;
      this.cdr.markForCheck();
    }
  }

  select(b: BookingDoc): void {
    this.selected = b;
    this.ownerNote = b.notes?.ownerNote || '';
    this.cdr.markForCheck();
  }

  async confirmSelected(): Promise<void> {
    if (!this.selected) return;
    this.actionLoading = true;
    this.cdr.markForCheck();

    try {
      await this.bookingSvc.confirmBoatBooking(this.selected);
      await this.refresh();
    } catch (e: any) {
      this.error = e?.message || 'Confirm failed.';
    } finally {
      this.actionLoading = false;
      this.cdr.markForCheck();
    }
  }

  async declineSelected(): Promise<void> {
    if (!this.selected) return;
    this.actionLoading = true;
    this.cdr.markForCheck();

    try {
      await this.bookingSvc.declineBooking(this.selected, this.ownerNote);
      await this.refresh();
    } catch (e: any) {
      this.error = e?.message || 'Decline failed.';
    } finally {
      this.actionLoading = false;
      this.cdr.markForCheck();
    }
  }

  async cancelSelected(): Promise<void> {
    if (!this.selected) return;
    this.actionLoading = true;
    this.cdr.markForCheck();

    try {
      await this.bookingSvc.cancelBookingAsOwner(this.selected, this.ownerNote);
      await this.refresh();
    } catch (e: any) {
      this.error = e?.message || 'Cancel failed.';
    } finally {
      this.actionLoading = false;
      this.cdr.markForCheck();
    }
  }

  trackByBookingId(_: number, b: BookingDoc) {
    return b.bookingId;
  }
}
